import{_ as o,a as d,d as e,e as a,f as r,g as n,h as s,i as l,j as c,k as i,b as h,c as p}from"./chunks/struct-to-json.p_GKhuop.js";import{_ as S,H as u,f as g,i as b}from"./chunks/framework.BIGTPeBz.js";const x=JSON.parse('{"title":"NS_HttpJson","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/ns-httpjson.md","filePath":"plugins/ns-httpjson.md"}'),N={name:"plugins/ns-httpjson.md"};function J(T,t,y,q,P,m){return u(),g("div",null,[...t[0]||(t[0]=[b('<h1 id="ns-httpjson" tabindex="-1">NS_HttpJson <a class="header-anchor" href="#ns-httpjson" aria-label="Permalink to &quot;NS_HttpJson&quot;">​</a></h1><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p>NS_HttpJson 是一套用于 <strong>HTTP 网络通信与 JSON 数据加工</strong> 的 UE 蓝图插件，通过一系列开箱即用的蓝图节点完成：</p><ul><li>HTTP 请求：支持 <code>GET</code> / <code>POST</code> / <code>PUT</code> / <code>DELETE</code> / <code>PATCH</code> 等请求方法，可自定义请求头（Header）与请求体（Post Data）</li><li>文件下载：支持下载进度反馈、保存路径控制、自动重命名与超时控制</li><li>文件上传：以 <code>multipart/form-data</code> 表单上传本地文件，支持额外表单字段与进度反馈</li><li>JSON 解析：按 <code>Key</code> 或点语法 <code>Path</code> 提取字符串 / 整数 / 浮点数 / 布尔值 / 数组，兼容“字符串包裹的嵌套 JSON”</li><li>JSON 构建与修改：<code>Map</code> / 数组一键序列化为 JSON，也可对已有 JSON 进行嵌套键值修改</li><li>结构体互转：自定义结构体与 JSON 相互转换，支持数组与 <code>FVector</code> / <code>FRotator</code> / <code>FTransform</code> 等常见类型</li></ul><p><strong>模块信息</strong></p><table class="ns-module-table"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块名</td><td><code>NS_HttpJson</code></td></tr><tr><td>模块类型</td><td>Runtime（加载阶段：PreLoadingScreen）</td></tr><tr><td>依赖模块</td><td>Core、CoreUObject、Engine、Slate、SlateCore、HTTP、Json、JsonUtilities</td></tr><tr><td>引擎版本</td><td>Unreal Engine 5.x（当前工程基于 UE 5.5）</td></tr><tr><td>支持平台</td><td>Win64、Mac、iOS、Android、Linux</td></tr><tr><td>核心类</td><td><code>UNS_HttpJsonAsyncAction</code>（HTTP 请求）、<code>UNS_FileUploadAsyncAction</code>（文件上传）、<code>UNS_FileDownloadAsyncAction</code>（文件下载）</td></tr><tr><td>辅助类</td><td><code>UNS_HttpJsonBPLibrary</code>（JSON 工具函数库）</td></tr><tr><td>蓝图分类</td><td>NS Http（请求 / 上传 / 下载）、NS Json（JSON 加工函数）</td></tr></tbody></table><blockquote><p>所有 HTTP 相关节点都是 <strong>异步动作（AsyncAction）</strong>：调用后立即返回，结果通过输出执行引脚（<code>On Completed</code>、<code>On Progress</code>）异步回调，不会阻塞游戏线程。</p></blockquote><h2 id="枚举" tabindex="-1">枚举 <a class="header-anchor" href="#枚举" aria-label="Permalink to &quot;枚举&quot;">​</a></h2><h3 id="ens-requesttype-请求类型" tabindex="-1">ENS_RequestType（请求类型） <a class="header-anchor" href="#ens-requesttype-请求类型" aria-label="Permalink to &quot;ENS_RequestType（请求类型）&quot;">​</a></h3><p><code>NS Send HTTP Request</code> 的请求方法选择项。</p><table tabindex="0"><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td>获取资源。<code>Post Data</code> 会作为查询参数拼接到 URL（如 <code>?a=1&amp;b=2</code>）</td></tr><tr><td>POST</td><td>提交数据。<code>Post Data</code> 会序列化为 JSON 请求体发送</td></tr><tr><td>PUT</td><td>整体更新资源。<code>Post Data</code> 会序列化为 JSON 请求体发送</td></tr><tr><td>DELETE</td><td>删除资源。<code>Post Data</code> 会作为查询参数拼接到 URL</td></tr><tr><td>PATCH</td><td>局部更新资源。<code>Post Data</code> 会序列化为 JSON 请求体发送</td></tr></tbody></table><h2 id="http-请求节点" tabindex="-1">HTTP 请求节点 <a class="header-anchor" href="#http-请求节点" aria-label="Permalink to &quot;HTTP 请求节点&quot;">​</a></h2><h3 id="ns-send-http-request【异步】" tabindex="-1"><span style="color:#41aef5;">NS Send HTTP Request</span>【异步】 <a class="header-anchor" href="#ns-send-http-request【异步】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Send HTTP Request&lt;/span&gt;【异步】&quot;">​</a></h3><p>通用的 HTTP 请求节点，支持全部五种请求方法、自定义 Header 与请求体数据。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>URL</td><td>String</td><td>-</td><td>目标 Web 服务器的完整地址，如 <code>https://api.example.com/data</code></td></tr><tr><td>Request Type</td><td>ENS_RequestType</td><td>GET</td><td>请求方法，见上表</td></tr><tr><td>Header</td><td>Map&lt;String, String&gt;</td><td>空</td><td>可选：自定义 HTTP 头，如 <code>Authorization</code>、<code>Accept</code> 等</td></tr><tr><td>Post Data</td><td>Map&lt;String, String&gt;</td><td>空</td><td>GET / DELETE 时作为查询参数；POST / PUT / PATCH 时作为请求体数据</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>请求超时时间（秒），超过仍未完成则按失败处理</td></tr></tbody></table><p><strong>输出（On Completed 之后）</strong></p><table tabindex="0"><thead><tr><th>输出</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Response Json</td><td>String</td><td>服务器返回的原始响应内容（通常为 JSON 字符串）</td></tr><tr><td>Response Code</td><td>Integer</td><td>服务器返回的 HTTP 状态码（200 表示成功）；网络错误 / 超时 / 无响应时为 <code>0</code></td></tr></tbody></table><p><strong>注意</strong></p><ul><li><code>Post Data</code> 无需手动拼成 JSON 字符串：POST / PUT / PATCH 时插件会把 Map 序列化为 JSON 对象，并<strong>自动设置 <code>Content-Type: application/json</code></strong></li><li>GET / DELETE 的 <code>Post Data</code> 按 <code>key=value&amp;...</code> 直接拼接查询串，不会做 URL 编码，特殊字符请自行处理</li><li>响应失败或没有收到有效响应时，<code>Response Json</code> 为空字符串、<code>Response Code</code> 为 <code>0</code>，请以此判断请求是否真正成功</li><li>可安全地并发发起多个请求，每个动作节点独立回调</li></ul><p><img src="'+o+'" alt="节点 - NSSendHttpRequest"></p><hr><h3 id="ns-download-file【异步】" tabindex="-1"><span style="color:#41aef5;">NS Download File</span>【异步】 <a class="header-anchor" href="#ns-download-file【异步】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Download File&lt;/span&gt;【异步】&quot;">​</a></h3><p>从指定 URL 下载文件并保存到本地，支持进度反馈、相对路径与超时控制。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>Download URL</td><td>String</td><td>-</td><td>文件的完整下载地址（HTTP / HTTPS）</td></tr><tr><td>Save Path</td><td>String</td><td>-</td><td>保存到的<strong>目录</strong>。勾选相对路径时基于 <code>[项目]/Content/</code> 目录</td></tr><tr><td>Is Relative Path</td><td>Boolean</td><td>true</td><td>true = <code>Save Path</code> 为相对路径；false = 绝对路径</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>下载超时时间（秒）</td></tr><tr><td>File Name Alias</td><td>String</td><td>空</td><td>可选：替换下载文件的文件名；留空则使用 URL 中的原始文件名</td></tr></tbody></table><p><strong>输出（On Completed 之后）</strong></p><table tabindex="0"><thead><tr><th>输出</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Success</td><td>Boolean</td><td>是否成功完成下载并写盘</td></tr><tr><td>Saved File Path</td><td>String</td><td>文件最终保存的完整路径</td></tr><tr><td>File Name</td><td>String</td><td>文件最终名称（可能已应用 Alias）</td></tr><tr><td>Progress Ratio</td><td>Float</td><td>进度比率，完成时为 <code>1.0</code></td></tr></tbody></table><p><strong>输出（On Progress 持续触发）</strong></p><table tabindex="0"><thead><tr><th>输出</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Progress Ratio</td><td>Float</td><td>当前下载进度比率（0.0 ~ 1.0）</td></tr><tr><td>Bytes Received</td><td>Integer64</td><td>已接收字节数</td></tr><tr><td>Total Bytes</td><td>Integer64</td><td>总字节数；服务器未返回 <code>Content-Length</code> 时为 <code>-1</code>（此时进度为估算值）</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>文件名默认取自 URL 路径最后一段（自动去掉查询参数）；URL 末尾无文件名时使用 <code>downloaded_file</code></li><li><code>File Name Alias</code> 只替换主文件名、<strong>保留原扩展名</strong>（例如 <code>a.zip</code> 传入 Alias=<code>my</code> 结果为 <code>my.zip</code>）；原文件无扩展名时直接使用 Alias</li><li>保存目录不存在时插件会自动创建（包括多级目录）</li><li>与上传不同，下载<strong>只判断是否收到有效响应</strong>，不校验状态码是否为 2xx，服务器返回 404 / 500 时其响应体也会被保存，请自行按业务校验</li><li>文件会先整体缓存在内存中再写盘，不适合下载超大文件</li></ul><p><img src="'+d+'" alt="节点 - NSDownloadFile"></p><hr><h3 id="ns-upload-file【异步】" tabindex="-1"><span style="color:#41aef5;">NS Upload File</span>【异步】 <a class="header-anchor" href="#ns-upload-file【异步】" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Upload File&lt;/span&gt;【异步】&quot;">​</a></h3><p>以 <code>multipart/form-data</code> 表单上传本地文件，支持进度跟踪、自定义 Header 与额外表单字段。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>Upload URL</td><td>String</td><td>-</td><td>服务器接收上传的接口地址</td></tr><tr><td>File Path</td><td>String</td><td>-</td><td>待上传的本地文件路径；相对路径基于 <code>[项目]/Content/</code> 目录</td></tr><tr><td>File Field Name</td><td>String</td><td>空</td><td>文件对应的表单字段名；留空默认 <code>file</code></td></tr><tr><td>Header</td><td>Map&lt;String, String&gt;</td><td>空</td><td>可选：自定义 HTTP 头（如认证 Token）</td></tr><tr><td>Post Data</td><td>Map&lt;String, String&gt;</td><td>空</td><td>可选：随请求一同发送的<strong>额外表单字段</strong>（如用户 ID、文件描述），会先于文件字段写入</td></tr><tr><td>Is Relative Path</td><td>Boolean</td><td>true</td><td>true = <code>File Path</code> 为相对路径；false = 绝对路径</td></tr><tr><td>Timeout</td><td>Float</td><td>120.0</td><td>上传超时时间（秒）</td></tr></tbody></table><p><strong>输出（On Completed 之后）</strong></p><table tabindex="0"><thead><tr><th>输出</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Success</td><td>Boolean</td><td>是否上传成功（响应状态码为 2xx）</td></tr><tr><td>Response Content</td><td>String</td><td>服务器返回的原始响应内容（通常是 JSON 反馈）</td></tr><tr><td>Response Code</td><td>Integer</td><td>服务器返回的 HTTP 状态码</td></tr><tr><td>Progress Ratio</td><td>Float</td><td>进度比率，完成时为 <code>1.0</code></td></tr></tbody></table><p><strong>输出（On Progress 持续触发）</strong></p><table tabindex="0"><thead><tr><th>输出</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Progress Ratio</td><td>Float</td><td>当前上传进度比率（0.0 ~ 1.0）</td></tr><tr><td>Bytes Sent</td><td>Integer64</td><td>已发送字节数</td></tr><tr><td>Total Bytes</td><td>Integer64</td><td>上传总字节数</td></tr></tbody></table><p><strong>注意</strong></p><ul><li>与下载不同，上传<strong>只有服务器返回 2xx 状态码才视为成功</strong>，否则 <code>Success = false</code>，<code>Response Content</code> 为服务器返回的错误信息</li><li>文件不存在或读取失败时会立即回调：<code>Success = false</code>、<code>Response Code = 0</code>，并在 <code>Response Content</code> 中给出原因（如 <code>File not found: xxx</code>）</li><li>文件字段的 <code>Content-Type</code> 固定为 <code>application/octet-stream</code>，Content-Type 边界由插件自动生成</li><li>上传方法固定为 <code>POST</code></li></ul><p><img src="'+e+'" alt="节点 - NSUploadFile"></p><h2 id="json-读取节点" tabindex="-1">JSON 读取节点 <a class="header-anchor" href="#json-读取节点" aria-label="Permalink to &quot;JSON 读取节点&quot;">​</a></h2><p>JSON 读取节点全部是<strong>纯函数（无执行引脚）</strong>，可在蓝图中直接作为取值节点使用。传入包含 JSON 的字符串即可得到结果。</p><p>按取值方式分为两类：</p><ul><li><strong>Value 系列</strong>：从 JSON <strong>最外层对象</strong>中按 <code>Key</code> 取值，适合单层结构</li><li><strong>Path 系列</strong>：按点语法 <code>Path</code>（如 <code>user.info.name</code>）直接深入到任意层级的嵌套字段</li></ul><blockquote><p>两类都兼容“字符串中包裹 JSON”的常见情况，即字段值本身是 <code>&quot;{...}&quot;</code> / <code>&quot;[...]&quot;</code> 形式的字符串时也能继续解析。</p></blockquote><h3 id="ns-json-value-to-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Json Value To String / Int / Float / Bool</span> <a class="header-anchor" href="#ns-json-value-to-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Value To String / Int / Float / Bool&lt;/span&gt;&quot;">​</a></h3><p>根据 <code>Key</code> 从 JSON 对象中提取对应值，并转换为指定类型。</p><p><strong>通用输入</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>待解析的 JSON 字符串（通常接自 <code>NS Send HTTP Request</code> 的 <code>Response Json</code>）</td></tr><tr><td>Key</td><td>String</td><td>目标键名。仅匹配最外层，例如 <code>{&quot;user_id&quot;: 123}</code> 取 <code>user_id</code></td></tr></tbody></table><p><strong>返回值</strong></p><table tabindex="0"><thead><tr><th>节点</th><th>返回类型</th><th>说明</th></tr></thead><tbody><tr><td>NS Json Value To String</td><td>String</td><td>字符串原样返回；数字 / 布尔转为字符串；对象 / 数组转为紧凑 JSON 字符串</td></tr><tr><td>NS Json Value To Int</td><td>Integer</td><td>数字取整返回</td></tr><tr><td>NS Json Value To Float</td><td>Float</td><td>数字返回</td></tr><tr><td>NS Json Value To Bool</td><td>Boolean</td><td>布尔返回</td></tr></tbody></table><p><strong>注意</strong>：找不到键、JSON 解析失败或类型不匹配时，String 返回空串、Int 返回 <code>0</code>、Float 返回 <code>0.0</code>、Bool 返回 <code>false</code>。</p><p><img src="'+a+'" alt="节点组 - NSJsonValueToType"></p><hr><h3 id="ns-json-path-to-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Json Path To String / Int / Float / Bool</span> <a class="header-anchor" href="#ns-json-path-to-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Path To String / Int / Float / Bool&lt;/span&gt;&quot;">​</a></h3><p>JSON 深层数据提取：使用点语法 <code>Path</code> 直接访问嵌套结构，无需多步解析。</p><p><strong>通用输入</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>待解析的 JSON 字符串</td></tr><tr><td>Path</td><td>String</td><td>点语法路径。例如从 <code>{&quot;user&quot;:{&quot;info&quot;:{&quot;name&quot;:&quot;Test&quot;}}}</code> 取名字，Path 填 <code>user.info.name</code></td></tr></tbody></table><p><strong>返回值</strong> 与 Value 系列相同（String / Int / Float / Bool），取值类型按使用节点而定。</p><p><strong>注意</strong>：路径中任意一段不存在、不是对象或无法继续深入时，返回对应类型的默认值（<code>&quot;&quot;</code> / <code>0</code> / <code>0.0</code> / <code>false</code>）；路径支持穿透“字符串包裹的 JSON 对象”。</p><p><img src="'+r+'" alt="节点组 - NSJsonPathToType"></p><hr><h3 id="ns-json-value-path-to-array" tabindex="-1"><span style="color:#41aef5;">NS Json Value / Path To Array</span> <a class="header-anchor" href="#ns-json-value-path-to-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Value / Path To Array&lt;/span&gt;&quot;">​</a></h3><p>把 JSON 数组提取为蓝图数组变量，共有 6 个节点：</p><table tabindex="0"><thead><tr><th>节点</th><th>输入</th><th>返回类型</th></tr></thead><tbody><tr><td>NS Json Value To Array (String)</td><td>Json String + Key</td><td>String 数组</td></tr><tr><td>NS Json Value To Array (Int)</td><td>Json String + Key</td><td>Integer 数组</td></tr><tr><td>NS Json Value To Array (Float)</td><td>Json String + Key</td><td>Float 数组</td></tr><tr><td>NS Json Path To Array (String)</td><td>Json String + Path</td><td>String 数组</td></tr><tr><td>NS Json Path To Array (Int)</td><td>Json String + Path</td><td>Integer 数组</td></tr><tr><td>NS Json Path To Array (Float)</td><td>Json String + Path</td><td>Float 数组</td></tr></tbody></table><p><strong>说明</strong></p><ul><li>兼容目标值是真正的数组（<code>&quot;scores&quot;:[10,20,30]</code>），也兼容字符串形式的数组（<code>&quot;scores&quot;:&quot;[10,20,30]&quot;</code>）</li><li>元素会自动做类型转换：例如 Int 数组会把数字、字符串（<code>Atoi</code>）、布尔（true=1）统一转为整数</li><li>Key / Path 不存在、不是数组或类型转换失败时返回<strong>空数组</strong>（不会报错）</li></ul><p><img src="'+n+'" alt="节点组 - NSJsonValuePathToArray"></p><h2 id="json-构建节点" tabindex="-1">JSON 构建节点 <a class="header-anchor" href="#json-构建节点" aria-label="Permalink to &quot;JSON 构建节点&quot;">​</a></h2><h3 id="ns-map-to-json" tabindex="-1"><span style="color:#41aef5;">NS Map To Json</span> <a class="header-anchor" href="#ns-map-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Map To Json&lt;/span&gt;&quot;">​</a></h3><p>把蓝图中的 <code>Map&lt;String, String&gt;</code> 序列化为 JSON 对象字符串，是构建 HTTP 请求体的核心工具。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Map</td><td>Map&lt;String, String&gt;</td><td>Map 的 Key 成为 JSON 字段名，Value 成为字段值</td></tr><tr><td>Return Value</td><td>String</td><td>序列化后的 JSON 字符串</td></tr></tbody></table><p><strong>自动嵌套规则</strong></p><p>Map 的 Value 若本身是合法的 <code>{...}</code> 对象或 <code>[...]</code> 数组文本，会自动被解析为嵌套的对象 / 数组；否则作为普通字符串值。</p><p>例如把 <strong>NS Int Array To Json</strong> 的输出（<code>[10,20,30]</code>）作为 Map 的某个 Value，最终会生成 <code>{&quot;user_id&quot;:&quot;101&quot;,&quot;scores&quot;:[10,20,30]}</code> 这样的嵌套 JSON。</p><blockquote><p>由于 <code>TMap</code> 底层无序，输出 JSON 的<strong>字段顺序不保证与添加顺序一致</strong>，请勿依赖字段顺序（JSON 语义本身也不依赖顺序）。</p></blockquote><p><img src="'+s+'" alt="节点 - NSMapToJson"></p><hr><h3 id="ns-string-int-float-array-to-json" tabindex="-1"><span style="color:#41aef5;">NS String / Int / Float Array To Json</span> <a class="header-anchor" href="#ns-string-int-float-array-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS String / Int / Float Array To Json&lt;/span&gt;&quot;">​</a></h3><p>把蓝图基本类型数组快速序列化为 JSON 数组字符串，共 3 个节点：</p><table tabindex="0"><thead><tr><th>节点</th><th>输入类型</th><th>返回</th><th>示例输出</th></tr></thead><tbody><tr><td>NS String Array To Json</td><td>String 数组</td><td>String</td><td><code>[&quot;item1&quot;,&quot;item2&quot;]</code></td></tr><tr><td>NS Int Array To Json</td><td>Integer 数组</td><td>String</td><td><code>[10,20,30]</code></td></tr><tr><td>NS Float Array To Json</td><td>Float 数组</td><td>String</td><td><code>[1.5,2.5]</code></td></tr></tbody></table><p><strong>说明</strong>：String 数组中元素若为 <code>{...}</code> / <code>[...]</code> 文本同样会被解析为嵌套对象 / 数组；序列化结果常作为子值（字符串）塞进 <strong>NS Map To Json</strong> 的 Map，用于构建复杂请求体。</p><p><img src="'+l+'" alt="节点组 - NSArrayToJson"></p><hr><h3 id="ns-json-array-to-string-array" tabindex="-1"><span style="color:#41aef5;">NS Json Array To String Array</span> <a class="header-anchor" href="#ns-json-array-to-string-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json Array To String Array&lt;/span&gt;&quot;">​</a></h3><p>把<strong>不含键名的纯数组字符串</strong>整体转换为 String 数组，用于处理服务器返回的 <code>[&quot;key1&quot;,&quot;key2&quot;,...]</code> 这类特殊接口。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json Array String</td><td>String</td><td>必须是 <code>[</code> <code>]</code> 包裹的有效 JSON 数组字符串，如 <code>[&quot;apple&quot;,&quot;banana&quot;]</code></td></tr><tr><td>Return Value</td><td>String 数组</td><td>转换后的字符串数组</td></tr></tbody></table><p><strong>说明</strong>：数组元素为数字、布尔、嵌套对象 / 数组时会一并转为字符串；输入完全无法解析时把原始输入作为单个元素返回。</p><p><img src="'+c+'" alt="节点 - NSJsonArrayToStringArray"></p><h2 id="json-修改节点" tabindex="-1">JSON 修改节点 <a class="header-anchor" href="#json-修改节点" aria-label="Permalink to &quot;JSON 修改节点&quot;">​</a></h2><h3 id="ns-set-json-value-string-int-float-bool" tabindex="-1"><span style="color:#41aef5;">NS Set Json Value (String / Int / Float / Bool)</span> <a class="header-anchor" href="#ns-set-json-value-string-int-float-bool" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Set Json Value (String / Int / Float / Bool)&lt;/span&gt;&quot;">​</a></h3><p>在已有 JSON 中设置（新增或覆盖）一个字段值，返回修改后的完整 JSON 字符串。共 4 个节点，按 Value 参数类型区分。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>原始 JSON 字符串</td></tr><tr><td>Key</td><td>String</td><td>字段键，<strong>支持点语法路径</strong>，如 <code>data.name</code> 表示修改嵌套字段</td></tr><tr><td>Value</td><td>String / Integer / Float / Boolean</td><td>要写入的值，按节点类型而定</td></tr><tr><td>Return Value</td><td>String</td><td>修改后的完整 JSON 字符串</td></tr></tbody></table><p><strong>注意</strong></p><ul><li><code>Key</code> 支持点号路径：路径上的中间节点不存在时<strong>自动创建为对象</strong>；中间节点是“字符串包裹的 JSON”时会先解析、修改后再回写为字符串</li><li>JSON 解析失败时原样返回输入的 <code>Json String</code>，不会丢失数据</li></ul><p><img src="'+i+'" alt="节点组 - NSSetJsonValue"></p><h2 id="结构体转换节点" tabindex="-1">结构体转换节点 <a class="header-anchor" href="#结构体转换节点" aria-label="Permalink to &quot;结构体转换节点&quot;">​</a></h2><p>结构体（Struct）与 JSON 互转节点基于反射实现，可配合 HTTP 响应做“JSON → 结构体变量”的强类型读取。</p><p>节点共 4 个，按<strong>转换方向</strong>分为两组：</p><ul><li><strong>解析方向（JSON → 结构体）</strong>：把 JSON 填充进结构体变量 —— <code>NS Json To Struct</code>（单个对象）、<code>NS Json To Struct Array</code>（对象数组）</li><li><strong>序列化方向（结构体 → JSON）</strong>：把结构体变量输出为 JSON 字符串 —— <code>NS Struct To Json</code>（单个结构体）、<code>NS Struct Array To Json</code>（结构体数组）</li></ul><p>两个方向共用同一套反射规则：</p><ul><li>字段名按结构体在编辑器中显示的名字匹配（区分大小写），JSON 中不存在对应字段的属性保持原值</li><li>支持 Bool / Int / Int64 / Float / String、嵌套结构体、一维基础数组，并额外支持 <code>FVector</code> / <code>FRotator</code> / <code>FTransform</code></li></ul><h3 id="解析方向-json-→-结构体" tabindex="-1">解析方向：JSON → 结构体 <a class="header-anchor" href="#解析方向-json-→-结构体" aria-label="Permalink to &quot;解析方向：JSON → 结构体&quot;">​</a></h3><p>将服务器返回的 JSON 直接解析到结构体变量中，避免逐字段取值。这两个节点都<strong>按引用直接修改目标变量（有执行引脚）</strong>；JSON 无效或字段缺失时保持原数据不变，可放心用于容错读取。</p><h4 id="ns-json-to-struct" tabindex="-1"><span style="color:#41aef5;">NS Json To Struct</span> <a class="header-anchor" href="#ns-json-to-struct" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json To Struct&lt;/span&gt;&quot;">​</a></h4><p>把单个 JSON 对象字符串按字段名填充到结构体变量中。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>待解析的 JSON 对象字符串</td></tr><tr><td>In Out Struct</td><td>任意结构体</td><td>目标结构体变量，调用后被填充</td></tr></tbody></table><blockquote><p><code>FVector</code> / <code>FRotator</code> / <code>FTransform</code> 在 JSON 中可以是对象形式（<code>{X,Y,Z}</code> / <code>{Pitch,Yaw,Roll}</code>），也可以是 UE 字符串形式。</p></blockquote><h4 id="ns-json-to-struct-array" tabindex="-1"><span style="color:#41aef5;">NS Json To Struct Array</span> <a class="header-anchor" href="#ns-json-to-struct-array" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Json To Struct Array&lt;/span&gt;&quot;">​</a></h4><p>把 JSON 数组字符串解析并填充到结构体数组变量中。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>Json String</td><td>String</td><td>待解析的 JSON 数组字符串</td></tr><tr><td>In Out Struct Array</td><td>结构体数组</td><td>目标结构体数组变量，调用后被填充</td></tr></tbody></table><blockquote><p>数组元素既可以是 JSON 对象，也可以是字符串形式的 JSON 对象；解析失败时数组保持不变。</p></blockquote><p><img src="'+h+'" alt="节点组 - NSJsonToStruct / NSJsonToStructArray"></p><hr><h3 id="序列化方向-结构体-→-json" tabindex="-1">序列化方向：结构体 → JSON <a class="header-anchor" href="#序列化方向-结构体-→-json" aria-label="Permalink to &quot;序列化方向：结构体 → JSON&quot;">​</a></h3><p>把结构体变量整体序列化为 JSON，常用于上传数据前把配置 / 结果对象打包成请求体。这两个节点均为<strong>纯函数</strong>。序列化失败时分别返回 <code>{}</code> / <code>[]</code>。</p><h4 id="ns-struct-to-json" tabindex="-1"><span style="color:#41aef5;">NS Struct To Json</span> <a class="header-anchor" href="#ns-struct-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Struct To Json&lt;/span&gt;&quot;">​</a></h4><p>把单个结构体序列化为 JSON 对象字符串。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>In Struct</td><td>任意结构体</td><td>待序列化的结构体变量</td></tr><tr><td>Return Value</td><td>String</td><td>JSON 字符串；序列化失败时返回 <code>{}</code></td></tr></tbody></table><blockquote><p><code>FVector</code> / <code>FRotator</code> / <code>FTransform</code> 会以 UE 的 <code>ToString</code> 字符串形式输出；嵌套结构体输出为 JSON 对象。</p></blockquote><h4 id="ns-struct-array-to-json" tabindex="-1"><span style="color:#41aef5;">NS Struct Array To Json</span> <a class="header-anchor" href="#ns-struct-array-to-json" aria-label="Permalink to &quot;&lt;span style=&quot;color:#41aef5&quot;&gt;NS Struct Array To Json&lt;/span&gt;&quot;">​</a></h4><p>把结构体数组序列化为 JSON 数组字符串。</p><table tabindex="0"><thead><tr><th>参数 / 返回</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>In Struct Array</td><td>结构体数组</td><td>元素必须是结构体</td></tr><tr><td>Return Value</td><td>String</td><td>JSON 数组字符串；序列化失败时返回 <code>[]</code></td></tr></tbody></table><p><img src="'+p+'" alt="节点组 - NSStructToJson / NSStructArrayToJson"></p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><p><strong>请求与回调</strong></p><ul><li><code>NS Send HTTP Request</code> 对成功 / 失败<strong>只回调一次</strong>：收到有效响应即回调并携带状态码，网络错误 / 超时则以空响应、状态码 <code>0</code> 回调</li><li>上传成功以上传 <code>2xx</code> 状态码为准；下载只判断“是否收到响应体”，不校验状态码</li><li>三个 HTTP 节点均为异步动作，内部注册到 GameInstance，可安全并发调用</li></ul></li><li><p><strong>Post Data / 请求体</strong></p><ul><li>GET / DELETE 的 <code>Post Data</code> 会拼成查询字符串（URL 已带 <code>?</code> 时自动追加 <code>&amp;</code>），<strong>不做 URL 编码</strong></li><li>POST / PUT / PATCH 的 <code>Post Data</code> 会序列化为 JSON 请求体，并自动写入 <code>Content-Type: application/json</code>（会覆盖 Header 中同名的预设值）</li></ul></li><li><p><strong>路径含义</strong></p><ul><li>上传 / 下载勾选 <code>Is Relative Path</code> 时，<code>File Path</code> / <code>Save Path</code> 均相对于 <code>[项目]/Content/</code> 目录（<code>ProjectContentDir</code>）</li><li>下载的 <code>Save Path</code> 指保存<strong>目录</strong>（目录不存在会自动创建），文件名由 URL 或 <code>File Name Alias</code> 决定</li></ul></li><li><p><strong>JSON 提取</strong></p><ul><li><code>NS Json Value To X</code> 只查最外层键，<code>NS Json Path To X</code> 用点语法查深层；两者都兼容“字符串包裹 JSON”的数据</li><li>提取失败不报错：String 返回空串、Int 返回 <code>0</code>、Float 返回 <code>0.0</code>、Bool 返回 <code>false</code>、数组返回空数组，请先自行确认字段存在</li></ul></li><li><p><strong>Map 转 JSON</strong></p><ul><li><code>TMap</code> 无序，<code>NS Map To Json</code> 输出的字段顺序不定；依赖顺序的服务端请改用结构体转换节点</li><li>借助 <code>[Type] Array To Json</code> 生成数组文本作为 Map 的 Value，再经 <code>NS Map To Json</code> 即可构建嵌套结构，这是组装复杂请求体的推荐姿势</li></ul></li><li><p><strong>结构体转换</strong></p><ul><li>字段名匹配编辑器中显示的名字，区分大小写；结构体建议使用 <code>BlueprintType</code> 以支持变量创建</li><li><code>NS Json To Struct</code> / <code>NS Json To Struct Array</code> 在 JSON 解析失败时保持原数据不变，可放心用于容错读取</li></ul></li></ol>',128)])])}const _=S(N,[["render",J]]);export{x as __pageData,_ as default};
